optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/evidence_validation.rs b/tools/bot-evaluation/src/evidence_validation.rs
index 5dfa8765..787f9cab 100644
--- a/tools/bot-evaluation/src/evidence_validation.rs
+++ b/tools/bot-evaluation/src/evidence_validation.rs
@@ -26,7 +26,7 @@ pub fn report(bytes: &[u8]) -> Result<()> {
         match reader.read_event()? {
             Event::Start(start) => {
                 if start.name().as_ref() == b"timeline"
-                    && path == [b"player-report".as_slice(), b"games", b"game"]
+                    && path == [0u8, 1, 2]
                 {
                     let content_start = reader.buffer_position() as usize;
                     let span = reader.read_to_end(start.name())?;
@@ -35,7 +35,7 @@ pub fn report(bytes: &[u8]) -> Result<()> {
                     skeleton.extend_from_slice(&bytes[copied..content_start]);
                     copied = content_end;
                 } else {
-                    path.push(start.name().as_ref().to_vec());
+                    path.push(match start.name().as_ref() { b"player-report" => 0u8, b"games" => 1, b"game" => 2, _ => 3 });
                 }
             }
             Event::End(_) => {
